import random
from itertools import combinations

N = 19

def has_short_cycle(adj, max_len=6):
    # BFS from each vertex, detect cycle of length <= max_len
    for s in range(N):
        # BFS with parent tracking
        dist = {s: 0}
        parent = {s: -1}
        from collections import deque
        q = deque([s])
        while q:
            u = q.popleft()
            if dist[u] > max_len // 2:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    # found cycle through s involving edge (u,v)
                    cyc_len = dist[u] + dist[v] + 1
                    if cyc_len <= max_len:
                        return True
    return False

def girth(adj):
    from collections import deque
    g = float('inf')
    for s in range(N):
        dist = {s: 0}
        parent = {s: -1}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    cyc_len = dist[u] + dist[v] + 1
                    if cyc_len < g:
                        g = cyc_len
    return g

