N = 19
TARGET_E = 28

# Variables:
# e[i][j] for i<j: edge exists
# c[v][k] for v in [0,N), k in [0,3): vertex v has color k
# Need: no triangle, no 4-cycle, no 5-cycle, no 6-cycle
# Coloring constraint: each v exactly one color; for each edge (u,v): not same color

var_counter = [1]
def new_var():
    v = var_counter[0]; var_counter[0] += 1; return v

edge_var = {}
for i in range(N):
    for j in range(i+1, N):
        edge_var[(i,j)] = new_var()

color_var = {}
for v in range(N):
    for k in range(3):
        color_var[(v,k)] = new_var()

clauses = []

# Each vertex exactly one color
for v in range(N):
    clauses.append([color_var[(v,0)], color_var[(v,1)], color_var[(v,2)]])
    for k1 in range(3):
        for k2 in range(k1+1,3):
            clauses.append([-color_var[(v,k1)], -color_var[(v,k2)]])

# For each edge: not same color
# edge(u,v) AND c(u,k) AND c(v,k) -> false
for (i,j), ev in edge_var.items():
    for k in range(3):
        clauses.append([-ev, -color_var[(i,k)], -color_var[(j,k)]])

# Girth >= 7: forbid cycles of length 3,4,5,6
# For each set of L distinct vertices forming a cycle, not all L edges present.
# Cycles of length L: choose L vertices, consider all cyclic orderings / L / 2

def get_edge(a,b):
    if a>b: a,b=b,a
    return edge_var[(a,b)]

# length 3: all triangles
for combo in combinations(range(N), 3):
    a,b,c = combo
    clauses.append([-get_edge(a,b), -get_edge(b,c), -get_edge(a,c)])

# length 4: 4-cycle a-b-c-d-a
# For each 4-subset, 3 possible 4-cycles
for combo in combinations(range(N), 4):
