    # cycles: abcd, abdc, acbd
    for (p,q,r,s) in [(a,b,c,d),(a,b,d,c),(a,c,b,d)]:
        clauses.append([-get_edge(p,q), -get_edge(q,r), -get_edge(r,s), -get_edge(s,p)])

